#!/usr/bin/env bash
# Frayd bootstrap (Linux/macOS) — generated by the web installer.
# Args: [--tunnel tailscale|cloudflared] [--] [LIBRARY_PATH]; everything after -- is the library path.
set -eo pipefail
LIB=""
TUNNEL_ARG=""
STARTED=""
while [ $# -gt 0 ]; do
  case "$1" in
    --tunnel) TUNNEL_ARG="${2:-}"; [ $# -ge 2 ] && shift; shift ;;
    --) shift; while [ $# -gt 0 ]; do LIB="$1"; shift; done ;;
    -*) echo "Unknown option: $1 (use [--tunnel tailscale|cloudflared] [--] [LIBRARY_PATH])" >&2; exit 2 ;;
    *) LIB="$1"; shift ;;
  esac
done
have() { command -v "$1" >/dev/null 2>&1; }
# Downloaded installers are removed on every exit, including a failed or interrupted download.
RUSTUP_INIT=""; TAILSCALE_INSTALL=""
remove_downloads() { rm -f ${RUSTUP_INIT:+"$RUSTUP_INIT"} ${TAILSCALE_INSTALL:+"$TAILSCALE_INSTALL"}; }
trap remove_downloads EXIT

echo "== Frayd installer =="
echo "Media folder: ${LIB:-<unset>}"

# --- deps ---
if have apt-get; then
  sudo apt-get update -qq && sudo apt-get install -y -qq git curl build-essential pkg-config libsqlite3-dev unzip unrar-free ffmpeg >/dev/null
elif have dnf; then
  sudo dnf install -y -q git curl gcc gcc-c++ make sqlite-devel unzip unrar ffmpeg >/dev/null
elif have pacman; then
  sudo pacman -S --noconfirm --needed git curl base-devel sqlite unzip unrar ffmpeg >/dev/null
elif have brew; then
  brew install -q git sqlite unzip unrar ffmpeg >/dev/null 2>&1 || true
fi

if ! have cargo; then
  echo "[*] Installing Rust toolchain..."
  # Download completely before running, so a truncated transfer never executes.
  RUSTUP_INIT="$(mktemp)"
  curl --proto '=https' --tlsv1.2 -sSf -o "$RUSTUP_INIT" https://sh.rustup.rs
  sh "$RUSTUP_INIT" -y --default-toolchain stable
  rm -f "$RUSTUP_INIT"
  # shellcheck source=/dev/null
  . "$HOME/.cargo/env"
fi

# --- clone / update ---
cd "$HOME"
if [ -d Frayd ]; then (cd Frayd && git pull --ff-only) else git clone https://github.com/kattiest/Frayd.git; fi

# --- library path ---
if [ -z "$LIB" ]; then
  printf "Path to your media folder [~/Media]: "
  read -r LIB
  LIB="${LIB:-$HOME/Media}"
fi
mkdir -p -- "$LIB"
LIB="$(cd -- "$LIB" && pwd)"

# --- build ---
echo "[*] Building (first build takes a few minutes)..."
cd Frayd/server
cargo build --release

# --- env file ---
tee .env >/dev/null <<EOF
FRAYD_LIBRARY=$LIB
# Public internet exposure? Uncomment for shorter sessions (days):
# FRAYD_SESSION_DAYS=7
EOF

# --- autostart: systemd user unit (Linux) or LaunchAgent (macOS) ---
if have systemctl; then
  mkdir -p "$HOME/.config/systemd/user"
  cat > "$HOME/.config/systemd/user/frayd.service" <<EOF
[Unit]
Description=Frayd media server
After=network-online.target

[Service]
WorkingDirectory=$PWD
EnvironmentFile=$PWD/.env
ExecStart=$PWD/target/release/frayd-server
Restart=on-failure

[Install]
WantedBy=default.target
EOF
  systemctl --user daemon-reload
  systemctl --user enable --now frayd.service
  loginctl show-user "$USER" >/dev/null 2>&1 && sudo loginctl enable-linger "$USER" 2>/dev/null || true
  echo "[OK] systemd user service installed (starts on boot)"
  STARTED=1
elif have launchctl; then
  mkdir -p "$HOME/Library/LaunchAgents"
  PL="$HOME/Library/LaunchAgents/io.github.kattiest.frayd.plist"
  cat > "$PL" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>io.github.kattiest.frayd</string>
  <key>WorkingDirectory</key><string>$PWD</string>
  <key>ProgramArguments</key><array><string>$PWD/target/release/frayd-server</string></array>
  <key>EnvironmentVariables</key><dict><key>FRAYD_LIBRARY</key><string>$LIB</string></dict>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
</dict></plist>
EOF
  launchctl load "$PL"
  echo "[OK] LaunchAgent installed (starts on login)"
  STARTED=1
else
  echo "[*] No systemd/launchd — start manually:"
  echo "    FRAYD_LIBRARY=$LIB ./target/release/frayd-server"
fi

# --- remote access (optional) ---
TUNNEL="${TUNNEL_ARG:-}"
if [ "$TUNNEL" = "tailscale" ]; then
  echo
  echo "== Tailscale remote access =="
  if ! have tailscale; then
    if have apt-get; then
      TAILSCALE_INSTALL="$(mktemp)"
      curl -fsSL -o "$TAILSCALE_INSTALL" https://tailscale.com/install.sh
      sh "$TAILSCALE_INSTALL"
      rm -f "$TAILSCALE_INSTALL"
    elif have dnf; then sudo dnf install -y tailscale
    elif have pacman; then sudo pacman -S --noconfirm --needed tailscale
    elif have brew; then brew install --cask tailscale
    fi
  fi
  echo "[*] Starting Tailscale — a browser window will open to log in."
  sudo tailscale up || echo "[!] tailscale up failed — run 'sudo tailscale up' later"
  echo "[OK] Your server's Tailscale address: $(tailscale ip -4 2>/dev/null || echo 'run: tailscale ip -4')"
  echo "     Install Tailscale on your phone/laptop, sign in with same account, then open that address:8484"
elif [ "$TUNNEL" = "cloudflared" ]; then
  echo
  echo "== Cloudflare Tunnel remote access =="
  if ! have cloudflared; then
    if have apt-get; then
      curl -fsSL https://pkg.cloudflare.com/cloudflare-main.gpg | sudo tee /usr/share/keyrings/cloudflare-main.gpg >/dev/null
      echo "deb [signed-by=/usr/share/keyrings/cloudflare-main.gpg] https://pkg.cloudflare.com/cloudflared any main" | sudo tee /etc/apt/sources.list.d/cloudflared.list
      sudo apt-get update -qq && sudo apt-get install -y -qq cloudflared
    elif have dnf; then sudo dnf install -y cloudflared
    elif have pacman; then sudo pacman -S --noconfirm --needed cloudflared
    elif have brew; then brew install cloudflared
    fi
  fi
  echo "[*] Next steps (needs interactive login):"
  echo "    1. cloudflared tunnel login            # opens browser to pick your domain"
  echo "    2. cloudflared tunnel create frayd"
  echo "    3. cloudflared tunnel route dns frayd media.yourdomain.com"
  echo "    4. cloudflared tunnel run frayd        # add --url http://localhost:8484"
  echo "  See https://developers.cloudflare.com/cloudflare/one-connections/connect-networks/ for the config file + autostart."
else
  echo
  echo "[*] Local network only. For remote access later, re-run the installer with the"
  echo "    remote access checkbox ticked (Tailscale or Cloudflare Tunnel)."
fi

echo
if [ -n "${STARTED:-}" ]; then
  echo "[OK] Frayd running at http://localhost:8484"
else
  echo "[*] Frayd is built; once started it serves http://localhost:8484"
fi
echo "     First login becomes the admin account."
